[metadata] {"type": "create", "filePath": "/workspace/repo/packages/insomnia/src/common/spectral-ruleset-validator.ts", "content": "import { parse } from 'yaml';

/**
 * Result of validating a Spectral ruleset.
 */
export type SpectralRulesetValidationResult =
  | { isValid: true }
  | { isValid: false; error: string };

/**
 * Normalizes a value into an array.
 *
 * - `undefined` becomes an empty array.
 * - a non-array value is wrapped in a single element array.
 * - an array is returned unchanged.
 */
export const toArray = <T>(value: T | T[] | undefined): T[] => {
  if (value === undefined) {
    return [];
  }
  return Array.isArray(value) ? value : [value];
};

// Tokens that can be used for prototype pollution.
const PROTO_TOKENS = ['__proto__', 'prototype', 'constructor'];

// Severity strings accepted as a rule shorthand.
const SEVERITY_STRINGS = new Set(['off', 'error', 'warn', 'info', 'hint']);

// Built-in Spectral functions.
const BUILTIN_FUNCTIONS = new Set([
  'alphabetical',
  'casing',
  'defined',
  'enumeration',
  'falsy',
  'length',
  'pattern',
  'schema',
  'truthy',
  'typedEnum',
  'undefined',
  'unreferencedReusableObject',
  'or',
  'xor',
]);

// Top-level keys we allow in a ruleset. Notably `functions` is NOT allowed as
// it would let a ruleset ship arbitrary executable code.
const ALLOWED_TOP_LEVEL_KEYS = new Set([
  'extends',
  'rules',
  'documentationUrl',
  'aliases',
  'overrides',
  'formats',
  'parserOptions',
  'except',
]);

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const invalid = (error: string): SpectralRulesetValidationResult => ({ isValid: false, error });

const containsProtoToken = (value: string): boolean =>
  PROTO_TOKENS.some(token => value.includes(token));

const validateDocumentationUrl = (value: unknown): SpectralRulesetValidationResult => {
  // Non-string documentationUrl values are skipped.
  if (typeof value !== 'string') {
    return { isValid: true };
  }
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:') {
      return invalid('"documentationUrl" must use the https scheme.');
    }
  } catch {
    return invalid('"documentationUrl" is not a valid https URL.');
  }
  return { isValid: true };
};

const validateThenEntry = (then: Record<string, unknown>): SpectralRulesetValidationResult => {
  if ('field' in then && typeof then.field === 'string') {
    const field = then.field;
    if (
      containsProtoToken(field) ||
      field.includes('.') ||
      field.includes('[') ||
      field.includes(']')
    ) {
      return invalid(`"then.field" contains a disallowed field name: ${field}`);
    }
  }

  if ('function' in then) {
    const fn = then.function;
    if (typeof fn !== 'string' || !BUILTIN_FUNCTIONS.has(fn)) {
      return invalid(`"then.function" is not an allowed built-in function: ${String(fn)}`);
    }
  }

  return { isValid: true };
};

const validateRuleBody = (body: Record<string, unknown>): SpectralRulesetValidationResult => {
  // `given` may be a single expression or an array of expressions.
  if ('given' in body) {
    for (const given of toArray(body.given)) {
      // Non-string given values are skipped.
      if (typeof given !== 'string') {
        continue;
      }
      if (containsProtoToken(given)) {
        return invalid(`"given" contains a disallowed token: ${given}`);
      }
    }
  }

  // `then` may be a single object or an array of objects.
  if ('then' in body) {
    for (const entry of toArray(body.then)) {
      // Non-object entries in a `then` array are skipped.
      if (!isPlainObject(entry)) {
        continue;
      }
      const result = validateThenEntry(entry);
      if (!result.isValid) {
        return result;
      }
    }
  }

  // Rules may also carry their own documentationUrl.
  const docResult = validateDocumentationUrl(body.documentationUrl);
  if (!docResult.isValid) {
    return docResult;
  }

  return { isValid: true };
};

const validateRules = (rules: unknown): SpectralRulesetValidationResult => {
  if (!isPlainObject(rules)) {
    return invalid('"rules" must be an object.');
  }

  for (const [name, body] of Object.entries(rules)) {
    if (isPlainObject(body)) {
      // Reject prototype-polluting rule names when the body is an object.
      if (PROTO_TOKENS.includes(name)) {
        return invalid(`Rule name "${name}" is not allowed.`);
      }
      const result = validateRuleBody(body);
      if (!result.isValid) {
        return result;
      }
      continue;
    }

    if (typeof body === 'boolean') {
      continue;
    }

    if (typeof body === 'string' && SEVERITY_STRINGS.has(body)) {
      continue;
    }

    return invalid(`Rule "${name}" must be an object, boolean, or severity string.`);
  }

  return { isValid: true };
};

/**
 * Validates the textual content of a Spectral ruleset (YAML or JSON).
 *
 * Returns `{ isValid: true }` for valid content, or `{ isValid: false, error }`
 * describing the first problem found.
 */
export const validateSpectralRuleset = (content: string): SpectralRulesetValidationResult => {
  if (!content || content.trim() === '') {
    return invalid('Ruleset content is empty.');
  }

  let parsed: unknown;
  try {
    parsed = parse(content);
  } catch {
    return invalid('Ruleset could not be parsed as YAML or JSON.');
  }

  if (!isPlainObject(parsed)) {
    return invalid('Ruleset must be an object.');
  }

  const keys = Object.keys(parsed);
  if (keys.length === 0) {
    return invalid('Ruleset must declare at least one of "extends" or "rules".');
  }

  for (const key of keys) {
    if (!ALLOWED_TOP_LEVEL_KEYS.has(key)) {
      return invalid(`Unsupported top-level key "${key}".`);
    }
  }

  if ('extends' in parsed) {
    for (const entry of toArray(parsed.extends)) {
      if (typeof entry !== 'string') {
        return invalid('"extends" entries must be strings.');
      }
    }
  }

  const docResult = validateDocumentationUrl(parsed.documentationUrl);
  if (!docResult.isValid) {
    return docResult;
  }

  if ('rules' in parsed) {
    const result = validateRules(parsed.rules);
    if (!result.isValid) {
      return result;
